import{_ as e,o as r,c as a,ae as o}from"./chunks/framework.EHGTsUvI.js";const g=JSON.parse('{"title":"P2P Stack","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/p2p.md","filePath":"architecture/p2p.md"}'),i={name:"architecture/p2p.md"};function n(s,t,d,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="p2p-stack" tabindex="-1">P2P Stack <a class="header-anchor" href="#p2p-stack" aria-label="Permalink to &quot;P2P Stack&quot;">​</a></h1><h2 id="transport-protocols" tabindex="-1">Transport Protocols <a class="header-anchor" href="#transport-protocols" aria-label="Permalink to &quot;Transport Protocols&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Use Case</th></tr></thead><tbody><tr><td><strong>BitTorrent/WebTorrent</strong></td><td>File transfer (data plane)</td></tr><tr><td><strong>DHT Kademlia</strong></td><td>Decentralized peer discovery</td></tr><tr><td><strong>BEP 44</strong></td><td>Signed mutable DHT data (handle→key mapping)</td></tr><tr><td><strong>mDNS/Bonjour</strong></td><td>LAN auto-discovery</td></tr><tr><td><strong>WebRTC</strong></td><td>Direct peer connections (NAT traversal)</td></tr><tr><td><strong>PAL/1.0</strong></td><td>Control plane (messaging, policy, key exchange)</td></tr></tbody></table><h2 id="transfer-routing" tabindex="-1">Transfer Routing <a class="header-anchor" href="#transfer-routing" aria-label="Permalink to &quot;Transfer Routing&quot;">​</a></h2><p>Palexplorer selects the best path automatically:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Path</th><th>Condition</th></tr></thead><tbody><tr><td>1</td><td><strong>LAN</strong></td><td>Same network (mDNS discovered) → Direct TCP</td></tr><tr><td>2</td><td><strong>Direct</strong></td><td>Public IP reachable → WebRTC or TCP</td></tr><tr><td>3</td><td><strong>Relay</strong></td><td>Both behind NAT → TURN server (Pro)</td></tr></tbody></table><p>Route probing (<code>route.probe</code> message) tests connectivity before large transfers.</p><h2 id="mdns-discovery" tabindex="-1">mDNS Discovery <a class="header-anchor" href="#mdns-discovery" aria-label="Permalink to &quot;mDNS Discovery&quot;">​</a></h2><ul><li>Service type: <code>_palexplorer._tcp</code></li><li>TXT records: <code>pk</code> (public key), <code>h</code> (handle), <code>n</code> (name), <code>tp</code> (torrent port), <code>wp</code> (web port)</li><li>Verification: Challenge with <code>type: status</code> before caching (prevents spoofing)</li><li>Caching: By public key only (handles are spoofable)</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nearby</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # List LAN peers</span></span></code></pre></div><h2 id="dht-mainline" tabindex="-1">DHT (Mainline) <a class="header-anchor" href="#dht-mainline" aria-label="Permalink to &quot;DHT (Mainline)&quot;">​</a></h2><p>BitTorrent Mainline DHT with BEP 44 mutable items for handle registration:</p><ul><li><strong>Salt</strong>: <code>&quot;pal:&lt;handle&gt;&quot;</code></li><li><strong>Value</strong>: <code>{h: handle, pk: publicKeyHex, t: timestamp, cap: &quot;sScr&quot;}</code></li><li><strong>Signed</strong>: Ed25519 (verified by DHT nodes)</li><li><strong>Lookup</strong>: <code>SHA-1(publicKey + salt)</code> → target hash</li></ul><h2 id="signaling-server" tabindex="-1">Signaling Server <a class="header-anchor" href="#signaling-server" aria-label="Permalink to &quot;Signaling Server&quot;">​</a></h2><p>Local TCP server on port 7474:</p><ul><li>Receives PAL/1.0 envelopes from peers</li><li>Handles share negotiation, sync handshake, policy updates</li><li>Not HTTP — native socket transport</li></ul><h2 id="webrtc" tabindex="-1">WebRTC <a class="header-anchor" href="#webrtc" aria-label="Permalink to &quot;WebRTC&quot;">​</a></h2><p>Used for direct peer connections when both peers are behind NAT:</p><ul><li>STUN: <code>stun:stun.l.google.com:19302</code> (default)</li><li>TURN: Credential provisioning via discovery server (Pro)</li><li>Data channels for file transfer</li><li>Media channels for streaming (Pro)</li></ul><h2 id="resilience" tabindex="-1">Resilience <a class="header-anchor" href="#resilience" aria-label="Permalink to &quot;Resilience&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Behavior</th></tr></thead><tbody><tr><td>Discovery server down</td><td>DHT + LAN still work</td></tr><tr><td>No internet</td><td>LAN sharing works</td></tr><tr><td>No peers online</td><td>Transfer queued, auto-resume</td></tr><tr><td>TURN server unavailable</td><td>Falls back to DHT relay</td></tr></tbody></table>',21)])])}const u=e(i,[["render",n]]);export{g as __pageData,u as default};
